	package day9;	import java.util.Arrays;	public class SortingViaMerge{		public static void order(int[] og, int start, int mid, int end){			int lSize = mid-start+1, rSize = end-mid;			int[] lArray = new  int[lSize];			int[] rArray = new int[rSize];			int indL=0,indR=0,indOg=0;			for(indL=0;indL<lSize;indL++)				lArray[indL] = og[start+indL];			for(indR=0;indR<rSize;indR++)				rArray[indR] = og[indR+mid+1];			indL=0; indR=0; indOg=start;			while(indL<lSize&&indR<rSize){				if(lArray[indL]>rArray[indR]) og[indOg] = rArray[indR++];				else og[indOg] = lArray[indL++];				indOg++;			}			while(indL<lSize) og[indOg++]=lArray[indL++];			while(indR<rSize) og[indOg++]=rArray[indR++];		}		public static void divide(int[] arr, int start, int end){			if(start<end){				int mid = start+(end-start)/2;				divide(arr,start,mid);				divide(arr,mid+1,end);				order(arr,start,mid,end);			}		}		public static void main(String[] ar){			int[] arr = {5,-6,19,16,0};			divide(arr,0,arr.length-1);			System.out.println(Arrays.toString(arr));		}	}